void __stdcall CreatePresetObject_Unused(int32_t nParam1, int32_t nParam2, D2PoolManagerStrc * pMemory, int32_t nParam3, int32_t nParam4) {
    D2PresetUnitStrc* pPresetUnit = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_OBJECT, nParam2, 0, nParam1, nParam3);
    pPresetUnit->nFlags |= 1;
    pPresetUnit->pPresetUnitNext = *(D2PresetUnitStrc**)(nParam4 + 0x38);
    *(D2PresetUnitStrc**)(nParam4 + 0x38) = (D2PresetUnitStrc*)pPresetUnit;
}

// Spawns repeated object presets (class 0x41) along a vertical line in world coords from start to end, spaced by 0x28. Prepends each to pMap->pPresetUnit and marks flag bit 0x1.
static void CreateObjectPresets(int nWorldX, int nWorldY, D2DrlgMapStrc * pMap, D2PoolManagerStrc * pMemory) {
    int32_t worldYStart = 0;
    int worldYEnd = pMap->pDrlgFile->nHeight + nWorldY;
    int worldX = nWorldX;
    int worldY = nWorldY;
    Transform::CoordsRoomToWorld(&worldX, &worldY);
    Transform::CoordsRoomToWorld(&worldYStart, &worldYEnd);
    while (worldY < worldYEnd) {
      D2PresetUnitStrc* pPreset;
      pPreset = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_OBJECT, 0x41, 0, worldX, worldY);
      pPreset->nFlags |= 1;
      pPreset->pPresetUnitNext = pMap->pPresetUnit;
      pMap->pPresetUnit = pPreset;
      worldY += 0x28;
    }
}

// Populates a vertical strip of the preset map with a row of five object presets per Y tile (IDs 0x28, 0x29, 0x29, 0x29, 0x2A at X offsets 0/+5/+10/+15/+20). Skips ahead by +3 rows when the grid cell has specific floor-type flags (type 4, certain subtypes), all linked into pMapStrc->pPresetUnit.
static void __stdcall CreateObjectPresets2(uint32_t xOffset, D2DrlgGridStrc * pGrid, D2PoolManagerStrc * pMemory, D2DrlgMapStrc * pMapStrc) {
    uint32_t cellFlags;
    int yIndex;
    int32_t worldY;
    int worldX;
    for (yIndex = 0; yIndex < pMapStrc->nSizeY; yIndex++) {
      D2PresetUnitStrc* pPreset;
      worldX = pMapStrc->nRealOffsetX + xOffset;
      worldY = pMapStrc->nRealOffsetY + yIndex;
      Transform::CoordsRoomToWorld(&worldX, &worldY);
      worldX += -5;
      pPreset = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_OBJECT, 0x28, 0, worldX, worldY);
      pPreset->nFlags |= 1;
      pPreset->pPresetUnitNext = pMapStrc->pPresetUnit;
      pMapStrc->pPresetUnit = pPreset;
      pPreset = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_OBJECT, 0x29, 0, worldX + 5, worldY);
      pPreset->nFlags |= 1;
      pPreset->pPresetUnitNext = pMapStrc->pPresetUnit;
      pMapStrc->pPresetUnit = pPreset;
      pPreset = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_OBJECT, 0x29, 0, worldX + 10, worldY);
      pPreset->nFlags |= 1;
      pPreset->pPresetUnitNext = pMapStrc->pPresetUnit;
      pMapStrc->pPresetUnit = pPreset;
      pPreset = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_OBJECT, 0x29, 0, worldX + 0xf, worldY);
      pPreset->nFlags |= 1;
      pPreset->pPresetUnitNext = pMapStrc->pPresetUnit;
      pMapStrc->pPresetUnit = pPreset;
      pPreset = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_OBJECT, 0x2a, 0, worldX + 0x14, worldY);
      pPreset->nFlags |= 1;
      pPreset->pPresetUnitNext = pMapStrc->pPresetUnit;
      pMapStrc->pPresetUnit = pPreset;
      cellFlags = DrlgGrid::GetGridFlags(pGrid, (int)xOffset <= 0 ? 0 : xOffset, yIndex);
      if (((uint8_t)(cellFlags >> 0x14) & 0x3f) == 4 && true) {
        switch (cellFlags >> 8 & 0xff) {
          case 0:

          case 4:

          case 8:

          case 0x10:

          case 0x1d:

          case 0x27:
            yIndex += 3;
        }
      }
    }
}

// Scans floor layer flags to decide object preset placement. Builds a sub-grid view, checks for a specific cell flag pattern (type 2, subtype 0x18), and invokes CreateObjectPresets/CreateObjectPresets2. Special-cases Def==0x1b to place globally.
static void CreateObjectPresetsForMap(D2DrlgMapStrc * pMapStrc, D2PoolManagerStrc * pMemory) {
    int floorFlagsBuf[256];
    D2DrlgGridStrc floorGrid;
    D2DrlgCoordStrc mapCoords;
    mapCoords.nHeight = pMapStrc->nSizeY;
    mapCoords.nWidth = pMapStrc->nSizeX;
    uint32_t xIndex = 0;
    mapCoords.nPosX = 0;
    mapCoords.nPosY = 0;
    DrlgGrid::FillExternalCellFlags(&floorGrid, (D2DrlgMapStrc*)pMapStrc->pDrlgFile->pFloorLayer[0], &mapCoords, mapCoords.nWidth + 1, floorFlagsBuf);
    mapCoords.nPosX = pMapStrc->nRealOffsetX;
    mapCoords.nPosY = pMapStrc->nRealOffsetY;
    if (pMapStrc->pTxtLevelPrest->Def != 0x1b) {
      uint32_t cellFlags;
      if (mapCoords.nWidth > 0) {
        do {
          cellFlags = DrlgGrid::GetGridFlags(&floorGrid, xIndex, 0);
          if (((uint8_t)(cellFlags >> 0x14) & 0x3f) == 2 && (char)(cellFlags >> 8) == '\x18') {
            CreateObjectPresets(xIndex + 1 + mapCoords.nPosX, mapCoords.nPosY, pMapStrc, pMemory);
            CreateObjectPresets2(xIndex, &floorGrid, pMemory, pMapStrc);
            xIndex += 4;
          }

          xIndex++;
        } while ((int)xIndex < mapCoords.nWidth);
      }

      DrlgGrid::ResetGrid(&floorGrid);
      return;
    }

    CreateObjectPresets(mapCoords.nPosX, mapCoords.nPosY, pMapStrc, pMemory);
    CreateObjectPresets2(-1, &floorGrid, pMemory, pMapStrc);
    DrlgGrid::ResetGrid(&floorGrid);
}

static void __stdcall CreateMonsterPreset(D2PoolManagerStrc * pMemory, D2DrlgMapStrc * pDrlgMap) {
    int32_t nX = pDrlgMap->nSizeX / 2 + pDrlgMap->nRealOffsetX;
    int32_t nY = pDrlgMap->nSizeY / 2 + pDrlgMap->nRealOffsetY;
    Transform::CoordsRoomToWorld(&nX, &nY);
    D2PresetUnitStrc* pPreset = DrlgRoom::AllocPresetUnit(nullptr, pMemory, UNIT_MONSTER, sgptDataTable->nTxtMonStatsSize > 0x10a ? 0x10a : -1, 1, nX, nY);
    pPreset->pPresetUnitNext = pDrlgMap->pPresetUnit;
    pDrlgMap->pPresetUnit = pPreset;
}

// Frees all tile grids associated with a preset room's D2DrlgPresetRoomStrc. The room data arrives in EAX and the pool manager in EDI; EAX was modelled as a local, so the reconstruction freed grids off an uninitialised pointer.
static void DRLGPRESET_FreePresetRoomGrids(void * pRoomExData, D2PoolManagerStrc * pPoolManagerStrc) {
    D2DrlgGridStrc* pGrid;
    int pPresetRoomDataRaw = *(int*)((int)pRoomExData + 0x20);
    if (!(pPresetRoomDataRaw && *(int*)(pPresetRoomDataRaw + 8))) {
      return;
    }

    int nFloorCount = *(int*)(*(int*)(pPresetRoomDataRaw + 8) + 0xc);
    if (!nFloorCount) {
      return;
    }

    int nWallCount = *(int*)(nFloorCount + 0x14);
    if (nWallCount > 0) {
      pGrid = (D2DrlgGridStrc*)(pPresetRoomDataRaw + 0x10);
      do {
        DrlgGrid::DRLGGRID_FreeGrid(pPoolManagerStrc, pGrid + 4);
        DrlgGrid::DRLGGRID_FreeGrid(pPoolManagerStrc, pGrid);
        pGrid++;
        nWallCount--;
      } while (nWallCount);
    }

    nFloorCount = *(int*)(nFloorCount + 0x18);
    if (nFloorCount > 0) {
      pGrid = (D2DrlgGridStrc*)(pPresetRoomDataRaw + 0xb0);
      do {
        DrlgGrid::DRLGGRID_FreeGrid(pPoolManagerStrc, pGrid);
        pGrid++;
        nFloorCount--;
      } while (nFloorCount);
    }

    DrlgGrid::DRLGGRID_FreeGrid(pPoolManagerStrc, (D2DrlgGridStrc*)(pPresetRoomDataRaw + 0xd8));
}

