// Decrements the ref-count on the global DS1 file cache entry for *ppDrlgFile under a critical section. If the count drops below 1, unlinks the node from gpDrlgFileCache, frees the DS1 data via DRLGPRESET_FreeDrlgFile, frees the cache node, and nulls *ppDrlgFile. No-op if *ppDrlgFile is already null.
// @sourcefile .\DRLG\Preset.cpp
void __fastcall DRLGPRESET_ReleaseDrlgFile(D2DrlgFileStrc * * ppDrlgFile) {
    if (!*ppDrlgFile) {
      return;
    }

    /* LPCRITICAL_SECTION lpCriticalSection for EnterCriticalSection */ EnterCriticalSection(&lpCriticalSection_0096d610);
    D2DrlgFileCacheNodeStrc* pCacheEntry = gpDrlgFileCache;
    D2DrlgFileCacheNodeStrc* pPrev = 0;
    if (gpDrlgFileCache) {
      D2DrlgFileCacheNodeStrc* pCurrent;
      pPrev = 0;
      do {
        pCurrent = pCacheEntry;
        pCacheEntry = pCurrent;
        if (pCurrent->pDrlgFile == *ppDrlgFile) {
          break;
        }

        pCacheEntry = pCurrent->pNext;
        pPrev = pCurrent;
      } while (pCacheEntry);
    }

    /* LONG * lpAddend for InterlockedDecrement */ InterlockedDecrement((LONG*)&pCacheEntry->nRefCount);
    if (pCacheEntry && (int)pCacheEntry->nRefCount <= 0) {
      if (pPrev) {
        pPrev->pNext = pCacheEntry->pNext;
      } else {
        gpDrlgFileCache = pCacheEntry->pNext;
      }

      /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(&lpCriticalSection_0096d610);
      DRLGPRESET_FreeDrlgFile(*ppDrlgFile);
      D2_FREE_POOL_AT(nullptr, pCacheEntry, ".\\DRLG\\Preset.cpp", 0x538);
      *ppDrlgFile = 0;
      return;
    }

    /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(&lpCriticalSection_0096d610);
}

// Walks the entire D2DrlgMapStrc linked list (pDrlgMap->pNext) and frees every allocation: grid (DRLGGRID_FreeGrid), vertices (DRLGVER_FreeVertices), DS1 file ref (DRLGPRESET_ReleaseDrlgFile), all preset units (including their path coordinate arrays), and the POPS placement arrays (pPopsIndex/SubIndex/Orientation/PosLocation). Finally frees each map node itself.
// @sourcefile .\DRLG\Preset.cpp
void __fastcall DRLGPRESET_FreeDrlgMapList(D2PoolManagerStrc * pMemory, D2DrlgMapStrc * pDrlgMap) {
    D2PresetUnitStrc* pNextPresetUnit;
    D2MapAIStrc* pPath;
    D2PresetUnitStrc* pPresetUnit;
    while (pDrlgMap) {
      D2DrlgMapStrc* pNext;
      pNext = pDrlgMap->pNext;
      DrlgGrid::DRLGGRID_FreeGrid(pMemory, &pDrlgMap->pMapGrid);
      DrlgVer::DRLGVER_FreeVertices(pMemory, &pDrlgMap->pVertices);
      DRLGPRESET_ReleaseDrlgFile(&pDrlgMap->pDrlgFile);
      pPresetUnit = pDrlgMap->pPresetUnit;
      while (pPresetUnit) {
        pPath = pPresetUnit->pMapAI;
        pNextPresetUnit = pPresetUnit->pPresetUnitNext;
        if (pPath) {
          D2_FREE_POOL_AT(pMemory, pPath->pPosition, ".\\DRLG\\Preset.cpp", 0x597);
          D2_FREE_POOL_AT(pMemory, pPath, ".\\DRLG\\Preset.cpp", 0x598);
        }

        D2_FREE_POOL_AT(pMemory, pPresetUnit, ".\\DRLG\\Preset.cpp", 0x56b);
        pPresetUnit = pNextPresetUnit;
      }

      if (pDrlgMap->pPopsIndex) {
        D2_FREE_POOL_AT(pMemory, pDrlgMap->pPopsIndex, ".\\DRLG\\Preset.cpp", 0x9fa);
      }
      if (pDrlgMap->pPopsSubIndex) {
        D2_FREE_POOL_AT(pMemory, pDrlgMap->pPopsSubIndex, ".\\DRLG\\Preset.cpp", 0x9fb);
      }
      if (pDrlgMap->pPopsOrientation) {
        D2_FREE_POOL_AT(pMemory, pDrlgMap->pPopsOrientation, ".\\DRLG\\Preset.cpp", 0x9fc);
      }
      if (pDrlgMap->pPosLocation) {
        D2_FREE_POOL_AT(pMemory, pDrlgMap->pPosLocation, ".\\DRLG\\Preset.cpp", 0x9fd);
      }

      D2_FREE_POOL_AT(pMemory, pDrlgMap, ".\\DRLG\\Preset.cpp", 0x9ff);
      pDrlgMap = pNext;
    }
}

// Searches for a matching preset type in the static preset type table. Compares the level ID, orientation bits, sub-type byte, and additional parameter against the table entries. Returns the matching index or -1 if not found. From Preset.cpp area.
int32_t __stdcall DRLGPRESET_FindPresetTypeIndex(int32_t nLevelType, uint32_t nOrientationFlags, uint32_t nSubIndex) {
    uint32_t nIndex;
    int* pTypeEntry;
    uint32_t* pTableEntry = (uint32_t*)&gPresetTypeTables.aIndex[0].nLastIndex;
    do {
      if (pTableEntry[-2] == nLevelType) {
        nIndex = pTableEntry[-1];
        if ((int)nIndex <= (int)*pTableEntry) {
          pTypeEntry = &gPresetTypeTables.aTypes[nIndex].nType;
          do {
            if ((nOrientationFlags >> 0x14 & 0x3f) == ((D2DrlgPresetTypeStrc*)(pTypeEntry - 1))->nOrientation && (nOrientationFlags >> 8 & 0xff) == *pTypeEntry && nSubIndex == pTypeEntry[1]) {
              return nIndex;
            }

            nIndex++;
            pTypeEntry += 7;
          } while ((int)nIndex <= (int)*pTableEntry);
        }
      }

      pTableEntry += 3;
      if ((int)pTableEntry >= (intptr_t)((char*)&gPresetTypeTables + 452)) {
        return -1;
      }
    } while (true);
}

